use serde::{Deserialize, Serialize};
use std::collections::HashMap;

impl < T > Slab < T > { # [doc = " Construct a new, empty `Slab`."] # [doc = ""] # [doc = " The function does not allocate and the returned slab will have no"] # [doc = " capacity until `insert` is called or capacity is explicitly reserved."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use slab::*;"] # [doc = " let slab: Slab<i32> = Slab::new();"] # [doc = " ```"] pub const fn new () -> Self { Self { entries : Vec :: new () , next : 0 , len : 0 , } } # [doc = " Construct a new, empty `Slab` with the specified capacity."] # [doc = ""] # [doc = " The returned slab will be able to store exactly `capacity` without"] # [doc = " reallocating. If `capacity` is 0, the slab will not allocate."] # [doc = ""] # [doc = " It is important to note that this function does not specify the *length*"] # [doc = " of the returned slab, but only the capacity. For an explanation of the"] # [doc = " difference between length and capacity, see [Capacity and"] # [doc = " reallocation](index.html#capacity-and-reallocation)."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use slab::*;"] # [doc = " let mut slab = Slab::with_capacity(10);"] # [doc = ""] # [doc = " // The slab contains no values, even though it has capacity for more"] # [doc = " assert_eq!(slab.len(), 0);"] # [doc = ""] # [doc = " // These are all done without reallocating..."] # [doc = " for i in 0..10 {"] # [doc = "     slab.insert(i);"] # [doc = " }"] # [doc = ""] # [doc = " // ...but this may make the slab reallocate"] # [doc = " slab.insert(11);"] # [doc = " ```"] pub fn with_capacity (capacity : usize) -> Slab < T > { Slab { entries : Vec :: with_capacity (capacity) , next : 0 , len : 0 , } } # [doc = " Return the number of values the slab can store without reallocating."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use slab::*;"] # [doc = " let slab: Slab<i32> = Slab::with_capacity(10);"] # [doc = " assert_eq!(slab.capacity(), 10);"] # [doc = " ```"] pub fn capacity (& self) -> usize { self . entries . capacity () } # [doc = " Reserve capacity for at least `additional` more values to be stored"] # [doc = " without allocating."] # [doc = ""] # [doc = " `reserve` does nothing if the slab already has sufficient capacity for"] # [doc = " `additional` more values. If more capacity is required, a new segment of"] # [doc = " memory will be allocated and all existing values will be copied into it."] # [doc = " As such, if the slab is already very large, a call to `reserve` can end"] # [doc = " up being expensive."] # [doc = ""] # [doc = " The slab may reserve more than `additional` extra space in order to"] # [doc = " avoid frequent reallocations. Use `reserve_exact` instead to guarantee"] # [doc = " that only the requested space is allocated."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " Panics if the new capacity exceeds `isize::MAX` bytes."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use slab::*;"] # [doc = " let mut slab = Slab::new();"] # [doc = " slab.insert(\"hello\");"] # [doc = " slab.reserve(10);"] # [doc = " assert!(slab.capacity() >= 11);"] # [doc = " ```"] pub fn reserve (& mut self , additional : usize) { if self . capacity () - self . len >= additional { return ; } let need_add = additional - (self . entries . len () - self . len) ; self . entries . reserve (need_add) ; } # [doc = " Reserve the minimum capacity required to store exactly `additional`"] # [doc = " more values."] # [doc = ""] # [doc = " `reserve_exact` does nothing if the slab already has sufficient capacity"] # [doc = " for `additional` more values. If more capacity is required, a new segment"] # [doc = " of memory will be allocated and all existing values will be copied into"] # [doc = " it.  As such, if the slab is already very large, a call to `reserve` can"] # [doc = " end up being expensive."] # [doc = ""] # [doc = " Note that the allocator may give the slab more space than it requests."] # [doc = " Therefore capacity can not be relied upon to be precisely minimal."] # [doc = " Prefer `reserve` if future insertions are expected."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " Panics if the new capacity exceeds `isize::MAX` bytes."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use slab::*;"] # [doc = " let mut slab = Slab::new();"] # [doc = " slab.insert(\"hello\");"] # [doc = " slab.reserve_exact(10);"] # [doc = " assert!(slab.capacity() >= 11);"] # [doc = " ```"] pub fn reserve_exact (& mut self , additional : usize) { if self . capacity () - self . len >= additional { return ; } let need_add = additional - (self . entries . len () - self . len) ; self . entries . reserve_exact (need_add) ; } # [doc = " Shrink the capacity of the slab as much as possible without invalidating keys."] # [doc = ""] # [doc = " Because values cannot be moved to a different index, the slab cannot"] # [doc = " shrink past any stored values."] # [doc = " It will drop down as close as possible to the length but the allocator may"] # [doc = " still inform the underlying vector that there is space for a few more elements."] # [doc = ""] # [doc = " This function can take O(n) time even when the capacity cannot be reduced"] # [doc = " or the allocation is shrunk in place. Repeated calls run in O(1) though."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use slab::*;"] # [doc = " let mut slab = Slab::with_capacity(10);"] # [doc = ""] # [doc = " for i in 0..3 {"] # [doc = "     slab.insert(i);"] # [doc = " }"] # [doc = ""] # [doc = " slab.shrink_to_fit();"] # [doc = " assert!(slab.capacity() >= 3 && slab.capacity() < 10);"] # [doc = " ```"] # [doc = ""] # [doc = " The slab cannot shrink past the last present value even if previous"] # [doc = " values are removed:"] # [doc = ""] # [doc = " ```"] # [doc = " # use slab::*;"] # [doc = " let mut slab = Slab::with_capacity(10);"] # [doc = ""] # [doc = " for i in 0..4 {"] # [doc = "     slab.insert(i);"] # [doc = " }"] # [doc = ""] # [doc = " slab.remove(0);"] # [doc = " slab.remove(3);"] # [doc = ""] # [doc = " slab.shrink_to_fit();"] # [doc = " assert!(slab.capacity() >= 3 && slab.capacity() < 10);"] # [doc = " ```"] pub fn shrink_to_fit (& mut self) { let len_before = self . entries . len () ; while let Some (& Entry :: Vacant (_)) = self . entries . last () { self . entries . pop () ; } if self . entries . len () != len_before { self . recreate_vacant_list () ; } self . entries . shrink_to_fit () ; } # [doc = " Iterate through all entries to recreate and repair the vacant list."] # [doc = " self.len must be correct and is not modified."] fn recreate_vacant_list (& mut self) { self . next = self . entries . len () ; let mut remaining_vacant = self . entries . len () - self . len ; if remaining_vacant == 0 { return ; } for (i , entry) in self . entries . iter_mut () . enumerate () . rev () { if let Entry :: Vacant (ref mut next) = * entry { * next = self . next ; self . next = i ; remaining_vacant -= 1 ; if remaining_vacant == 0 { break ; } } } } # [doc = " Reduce the capacity as much as possible, changing the key for elements when necessary."] # [doc = ""] # [doc = " To allow updating references to the elements which must be moved to a new key,"] # [doc = " this function takes a closure which is called before moving each element."] # [doc = " The second and third parameters to the closure are the current key and"] # [doc = " new key respectively."] # [doc = " In case changing the key for one element turns out not to be possible,"] # [doc = " the move can be cancelled by returning `false` from the closure."] # [doc = " In that case no further attempts at relocating elements is made."] # [doc = " If the closure unwinds, the slab will be left in a consistent state,"] # [doc = " but the value that the closure panicked on might be removed."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use slab::*;"] # [doc = ""] # [doc = " let mut slab = Slab::with_capacity(10);"] # [doc = " let a = slab.insert('a');"] # [doc = " slab.insert('b');"] # [doc = " slab.insert('c');"] # [doc = " slab.remove(a);"] # [doc = " slab.compact(|&mut value, from, to| {"] # [doc = "     assert_eq!((value, from, to), ('c', 2, 0));"] # [doc = "     true"] # [doc = " });"] # [doc = " assert!(slab.capacity() >= 2 && slab.capacity() < 10);"] # [doc = " ```"] # [doc = ""] # [doc = " The value is not moved when the closure returns `Err`:"] # [doc = ""] # [doc = " ```"] # [doc = " # use slab::*;"] # [doc = ""] # [doc = " let mut slab = Slab::with_capacity(100);"] # [doc = " let a = slab.insert('a');"] # [doc = " let b = slab.insert('b');"] # [doc = " slab.remove(a);"] # [doc = " slab.compact(|&mut value, from, to| false);"] # [doc = " assert_eq!(slab.iter().next(), Some((b, &'b')));"] # [doc = " ```"] pub fn compact < F > (& mut self , mut rekey : F) where F : FnMut (& mut T , usize , usize) -> bool , { struct CleanupGuard < 'a , T > { slab : & 'a mut Slab < T > , decrement : bool , } impl < T > Drop for CleanupGuard < '_ , T > { fn drop (& mut self) { if self . decrement { self . slab . len -= 1 ; } self . slab . recreate_vacant_list () ; } } let mut guard = CleanupGuard { slab : self , decrement : true , } ; let mut occupied_until = 0 ; while guard . slab . entries . len () > guard . slab . len { if let Some (Entry :: Occupied (mut value)) = guard . slab . entries . pop () { while let Some (& Entry :: Occupied (_)) = guard . slab . entries . get (occupied_until) { occupied_until += 1 ; } if ! rekey (& mut value , guard . slab . entries . len () , occupied_until) { guard . slab . entries . push (Entry :: Occupied (value)) ; guard . decrement = false ; guard . slab . entries . shrink_to_fit () ; return ; } guard . slab . entries [occupied_until] = Entry :: Occupied (value) ; occupied_until += 1 ; } } guard . slab . next = guard . slab . len ; guard . slab . entries . shrink_to_fit () ; mem :: forget (guard) ; } # [doc = " Clear the slab of all values."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use slab::*;"] # [doc = " let mut slab = Slab::new();"] # [doc = ""] # [doc = " for i in 0..3 {"] # [doc = "     slab.insert(i);"] # [doc = " }"] # [doc = ""] # [doc = " slab.clear();"] # [doc = " assert!(slab.is_empty());"] # [doc = " ```"] pub fn clear (& mut self) { self . entries . clear () ; self . len = 0 ; self . next = 0 ; } # [doc = " Return the number of stored values."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use slab::*;"] # [doc = " let mut slab = Slab::new();"] # [doc = ""] # [doc = " for i in 0..3 {"] # [doc = "     slab.insert(i);"] # [doc = " }"] # [doc = ""] # [doc = " assert_eq!(3, slab.len());"] # [doc = " ```"] pub fn len (& self) -> usize { self . len } # [doc = " Return `true` if there are no values stored in the slab."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use slab::*;"] # [doc = " let mut slab = Slab::new();"] # [doc = " assert!(slab.is_empty());"] # [doc = ""] # [doc = " slab.insert(1);"] # [doc = " assert!(!slab.is_empty());"] # [doc = " ```"] pub fn is_empty (& self) -> bool { self . len == 0 } # [doc = " Return an iterator over the slab."] # [doc = ""] # [doc = " This function should generally be **avoided** as it is not efficient."] # [doc = " Iterators must iterate over every slot in the slab even if it is"] # [doc = " vacant. As such, a slab with a capacity of 1 million but only one"] # [doc = " stored value must still iterate the million slots."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use slab::*;"] # [doc = " let mut slab = Slab::new();"] # [doc = ""] # [doc = " for i in 0..3 {"] # [doc = "     slab.insert(i);"] # [doc = " }"] # [doc = ""] # [doc = " let mut iterator = slab.iter();"] # [doc = ""] # [doc = " assert_eq!(iterator.next(), Some((0, &0)));"] # [doc = " assert_eq!(iterator.next(), Some((1, &1)));"] # [doc = " assert_eq!(iterator.next(), Some((2, &2)));"] # [doc = " assert_eq!(iterator.next(), None);"] # [doc = " ```"] pub fn iter (& self) -> Iter < '_ , T > { Iter { entries : self . entries . iter () . enumerate () , len : self . len , } } # [doc = " Return an iterator that allows modifying each value."] # [doc = ""] # [doc = " This function should generally be **avoided** as it is not efficient."] # [doc = " Iterators must iterate over every slot in the slab even if it is"] # [doc = " vacant. As such, a slab with a capacity of 1 million but only one"] # [doc = " stored value must still iterate the million slots."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use slab::*;"] # [doc = " let mut slab = Slab::new();"] # [doc = ""] # [doc = " let key1 = slab.insert(0);"] # [doc = " let key2 = slab.insert(1);"] # [doc = ""] # [doc = " for (key, val) in slab.iter_mut() {"] # [doc = "     if key == key1 {"] # [doc = "         *val += 2;"] # [doc = "     }"] # [doc = " }"] # [doc = ""] # [doc = " assert_eq!(slab[key1], 2);"] # [doc = " assert_eq!(slab[key2], 1);"] # [doc = " ```"] pub fn iter_mut (& mut self) -> IterMut < '_ , T > { IterMut { entries : self . entries . iter_mut () . enumerate () , len : self . len , } } # [doc = " Return a reference to the value associated with the given key."] # [doc = ""] # [doc = " If the given key is not associated with a value, then `None` is"] # [doc = " returned."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use slab::*;"] # [doc = " let mut slab = Slab::new();"] # [doc = " let key = slab.insert(\"hello\");"] # [doc = ""] # [doc = " assert_eq!(slab.get(key), Some(&\"hello\"));"] # [doc = " assert_eq!(slab.get(123), None);"] # [doc = " ```"] pub fn get (& self , key : usize) -> Option < & T > { match self . entries . get (key) { Some (Entry :: Occupied (val)) => Some (val) , _ => None , } } # [doc = " Return a mutable reference to the value associated with the given key."] # [doc = ""] # [doc = " If the given key is not associated with a value, then `None` is"] # [doc = " returned."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use slab::*;"] # [doc = " let mut slab = Slab::new();"] # [doc = " let key = slab.insert(\"hello\");"] # [doc = ""] # [doc = " *slab.get_mut(key).unwrap() = \"world\";"] # [doc = ""] # [doc = " assert_eq!(slab[key], \"world\");"] # [doc = " assert_eq!(slab.get_mut(123), None);"] # [doc = " ```"] pub fn get_mut (& mut self , key : usize) -> Option < & mut T > { match self . entries . get_mut (key) { Some (& mut Entry :: Occupied (ref mut val)) => Some (val) , _ => None , } } # [doc = " Return two mutable references to the values associated with the two"] # [doc = " given keys simultaneously."] # [doc = ""] # [doc = " If any one of the given keys is not associated with a value, then `None`"] # [doc = " is returned."] # [doc = ""] # [doc = " This function can be used to get two mutable references out of one slab,"] # [doc = " so that you can manipulate both of them at the same time, eg. swap them."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " This function will panic if `key1` and `key2` are the same."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use slab::*;"] # [doc = " use std::mem;"] # [doc = ""] # [doc = " let mut slab = Slab::new();"] # [doc = " let key1 = slab.insert(1);"] # [doc = " let key2 = slab.insert(2);"] # [doc = " let (value1, value2) = slab.get2_mut(key1, key2).unwrap();"] # [doc = " mem::swap(value1, value2);"] # [doc = " assert_eq!(slab[key1], 2);"] # [doc = " assert_eq!(slab[key2], 1);"] # [doc = " ```"] pub fn get2_mut (& mut self , key1 : usize , key2 : usize) -> Option < (& mut T , & mut T) > { assert ! (key1 != key2) ; let (entry1 , entry2) ; if key1 > key2 { let (slice1 , slice2) = self . entries . split_at_mut (key1) ; entry1 = slice2 . get_mut (0) ; entry2 = slice1 . get_mut (key2) ; } else { let (slice1 , slice2) = self . entries . split_at_mut (key2) ; entry1 = slice1 . get_mut (key1) ; entry2 = slice2 . get_mut (0) ; } match (entry1 , entry2) { (Some (& mut Entry :: Occupied (ref mut val1)) , Some (& mut Entry :: Occupied (ref mut val2)) ,) => Some ((val1 , val2)) , _ => None , } } # [doc = " Returns mutable references to many indices at once."] # [doc = ""] # [doc = " Returns [`GetDisjointMutError`] if the indices are out of bounds,"] # [doc = " overlapping, or vacant."] pub fn get_disjoint_mut < const N : usize > (& mut self , keys : [usize ; N] ,) -> Result < [& mut T ; N] , GetDisjointMutError > { for (i , & key) in keys . iter () . enumerate () { for & prev_key in & keys [.. i] { if key == prev_key { return Err (GetDisjointMutError :: OverlappingIndices) ; } } } let entries_ptr = self . entries . as_mut_ptr () ; let entries_len = self . entries . len () ; let mut res = MaybeUninit :: < [& mut T ; N] > :: uninit () ; let res_ptr = res . as_mut_ptr () as * mut & mut T ; for (i , & key) in keys . iter () . enumerate () { if key >= entries_len { return Err (GetDisjointMutError :: IndexOutOfBounds) ; } match unsafe { & mut * entries_ptr . add (key) } { Entry :: Vacant (_) => return Err (GetDisjointMutError :: IndexVacant) , Entry :: Occupied (entry) => { unsafe { res_ptr . add (i) . write (entry) } ; } } } Ok (unsafe { res . assume_init () }) } # [doc = " Return a reference to the value associated with the given key without"] # [doc = " performing bounds checking."] # [doc = ""] # [doc = " For a safe alternative see [`get`](Slab::get)."] # [doc = ""] # [doc = " This function should be used with care."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " The key must be within bounds."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use slab::*;"] # [doc = " let mut slab = Slab::new();"] # [doc = " let key = slab.insert(2);"] # [doc = ""] # [doc = " unsafe {"] # [doc = "     assert_eq!(slab.get_unchecked(key), &2);"] # [doc = " }"] # [doc = " ```"] pub unsafe fn get_unchecked (& self , key : usize) -> & T { match * self . entries . get_unchecked (key) { Entry :: Occupied (ref val) => val , _ => unreachable ! () , } } # [doc = " Return a mutable reference to the value associated with the given key"] # [doc = " without performing bounds checking."] # [doc = ""] # [doc = " For a safe alternative see [`get_mut`](Slab::get_mut)."] # [doc = ""] # [doc = " This function should be used with care."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " The key must be within bounds."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use slab::*;"] # [doc = " let mut slab = Slab::new();"] # [doc = " let key = slab.insert(2);"] # [doc = ""] # [doc = " unsafe {"] # [doc = "     let val = slab.get_unchecked_mut(key);"] # [doc = "     *val = 13;"] # [doc = " }"] # [doc = ""] # [doc = " assert_eq!(slab[key], 13);"] # [doc = " ```"] pub unsafe fn get_unchecked_mut (& mut self , key : usize) -> & mut T { match * self . entries . get_unchecked_mut (key) { Entry :: Occupied (ref mut val) => val , _ => unreachable ! () , } } # [doc = " Return two mutable references to the values associated with the two"] # [doc = " given keys simultaneously without performing bounds checking and safety"] # [doc = " condition checking."] # [doc = ""] # [doc = " For a safe alternative see [`get2_mut`](Slab::get2_mut)."] # [doc = ""] # [doc = " This function should be used with care."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " - Both keys must be within bounds."] # [doc = " - The condition `key1 != key2` must hold."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use slab::*;"] # [doc = " use std::mem;"] # [doc = ""] # [doc = " let mut slab = Slab::new();"] # [doc = " let key1 = slab.insert(1);"] # [doc = " let key2 = slab.insert(2);"] # [doc = " let (value1, value2) = unsafe { slab.get2_unchecked_mut(key1, key2) };"] # [doc = " mem::swap(value1, value2);"] # [doc = " assert_eq!(slab[key1], 2);"] # [doc = " assert_eq!(slab[key2], 1);"] # [doc = " ```"] pub unsafe fn get2_unchecked_mut (& mut self , key1 : usize , key2 : usize) -> (& mut T , & mut T) { debug_assert_ne ! (key1 , key2) ; let ptr = self . entries . as_mut_ptr () ; let ptr1 = ptr . add (key1) ; let ptr2 = ptr . add (key2) ; match (& mut * ptr1 , & mut * ptr2) { (& mut Entry :: Occupied (ref mut val1) , & mut Entry :: Occupied (ref mut val2)) => { (val1 , val2) } _ => unreachable ! () , } } # [doc = " Get the key for an element in the slab."] # [doc = ""] # [doc = " The reference must point to an element owned by the slab."] # [doc = " Otherwise this function will panic."] # [doc = " This is a constant-time operation because the key can be calculated"] # [doc = " from the reference with pointer arithmetic."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " This function will panic if the reference does not point to an element"] # [doc = " of the slab."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use slab::*;"] # [doc = ""] # [doc = " let mut slab = Slab::new();"] # [doc = " let key = slab.insert(String::from(\"foo\"));"] # [doc = " let value = &slab[key];"] # [doc = " assert_eq!(slab.key_of(value), key);"] # [doc = " ```"] # [doc = ""] # [doc = " Values are not compared, so passing a reference to a different location"] # [doc = " will result in a panic:"] # [doc = ""] # [doc = " ```should_panic"] # [doc = " # use slab::*;"] # [doc = ""] # [doc = " let mut slab = Slab::new();"] # [doc = " let key = slab.insert(0);"] # [doc = " let bad = &0;"] # [doc = " slab.key_of(bad); // this will panic"] # [doc = " unreachable!();"] # [doc = " ```"] # [track_caller] pub fn key_of (& self , present_element : & T) -> usize { let element_ptr = present_element as * const T as usize ; let base_ptr = self . entries . as_ptr () as usize ; let byte_offset = element_ptr . wrapping_sub (base_ptr) ; let key = byte_offset / mem :: size_of :: < Entry < T > > () ; if key >= self . entries . len () { panic ! ("The reference points to a value outside this slab") ; } key } # [doc = " Insert a value in the slab, returning key assigned to the value."] # [doc = ""] # [doc = " The returned key can later be used to retrieve or remove the value using indexed"] # [doc = " lookup and `remove`. Additional capacity is allocated if needed. See"] # [doc = " [Capacity and reallocation](index.html#capacity-and-reallocation)."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " Panics if the new storage in the vector exceeds `isize::MAX` bytes."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use slab::*;"] # [doc = " let mut slab = Slab::new();"] # [doc = " let key = slab.insert(\"hello\");"] # [doc = " assert_eq!(slab[key], \"hello\");"] # [doc = " ```"] pub fn insert (& mut self , val : T) -> usize { let key = self . next ; self . insert_at (key , val) ; key } # [doc = " Returns the key of the next vacant entry."] # [doc = ""] # [doc = " This function returns the key of the vacant entry which  will be used"] # [doc = " for the next insertion. This is equivalent to"] # [doc = " `slab.vacant_entry().key()`, but it doesn't require mutable access."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use slab::*;"] # [doc = " let mut slab = Slab::new();"] # [doc = " assert_eq!(slab.vacant_key(), 0);"] # [doc = ""] # [doc = " slab.insert(0);"] # [doc = " assert_eq!(slab.vacant_key(), 1);"] # [doc = ""] # [doc = " slab.insert(1);"] # [doc = " slab.remove(0);"] # [doc = " assert_eq!(slab.vacant_key(), 0);"] # [doc = " ```"] pub fn vacant_key (& self) -> usize { self . next } # [doc = " Return a handle to a vacant entry allowing for further manipulation."] # [doc = ""] # [doc = " This function is useful when creating values that must contain their"] # [doc = " slab key. The returned `VacantEntry` reserves a slot in the slab and is"] # [doc = " able to query the associated key."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use slab::*;"] # [doc = " let mut slab = Slab::new();"] # [doc = ""] # [doc = " let hello = {"] # [doc = "     let entry = slab.vacant_entry();"] # [doc = "     let key = entry.key();"] # [doc = ""] # [doc = "     entry.insert((key, \"hello\"));"] # [doc = "     key"] # [doc = " };"] # [doc = ""] # [doc = " assert_eq!(hello, slab[hello].0);"] # [doc = " assert_eq!(\"hello\", slab[hello].1);"] # [doc = " ```"] pub fn vacant_entry (& mut self) -> VacantEntry < '_ , T > { VacantEntry { key : self . next , slab : self , } } fn insert_at (& mut self , key : usize , val : T) { self . len += 1 ; if key == self . entries . len () { self . entries . push (Entry :: Occupied (val)) ; self . next = key + 1 ; } else { self . next = match self . entries . get (key) { Some (& Entry :: Vacant (next)) => next , _ => unreachable ! () , } ; self . entries [key] = Entry :: Occupied (val) ; } } # [doc = " Tries to remove the value associated with the given key,"] # [doc = " returning the value if the key existed."] # [doc = ""] # [doc = " The key is then released and may be associated with future stored"] # [doc = " values."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use slab::*;"] # [doc = " let mut slab = Slab::new();"] # [doc = ""] # [doc = " let hello = slab.insert(\"hello\");"] # [doc = ""] # [doc = " assert_eq!(slab.try_remove(hello), Some(\"hello\"));"] # [doc = " assert!(!slab.contains(hello));"] # [doc = " ```"] pub fn try_remove (& mut self , key : usize) -> Option < T > { if let Some (entry) = self . entries . get_mut (key) { let prev = mem :: replace (entry , Entry :: Vacant (self . next)) ; match prev { Entry :: Occupied (val) => { self . len -= 1 ; self . next = key ; return val . into () ; } _ => { * entry = prev ; } } } None } # [doc = " Remove and return the value associated with the given key."] # [doc = ""] # [doc = " The key is then released and may be associated with future stored"] # [doc = " values."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " Panics if `key` is not associated with a value."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use slab::*;"] # [doc = " let mut slab = Slab::new();"] # [doc = ""] # [doc = " let hello = slab.insert(\"hello\");"] # [doc = ""] # [doc = " assert_eq!(slab.remove(hello), \"hello\");"] # [doc = " assert!(!slab.contains(hello));"] # [doc = " ```"] # [track_caller] pub fn remove (& mut self , key : usize) -> T { self . try_remove (key) . expect ("invalid key") } # [doc = " Return `true` if a value is associated with the given key."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use slab::*;"] # [doc = " let mut slab = Slab::new();"] # [doc = ""] # [doc = " let hello = slab.insert(\"hello\");"] # [doc = " assert!(slab.contains(hello));"] # [doc = ""] # [doc = " slab.remove(hello);"] # [doc = ""] # [doc = " assert!(!slab.contains(hello));"] # [doc = " ```"] pub fn contains (& self , key : usize) -> bool { matches ! (self . entries . get (key) , Some (& Entry :: Occupied (_))) } # [doc = " Retain only the elements specified by the predicate."] # [doc = ""] # [doc = " In other words, remove all elements `e` such that `f(usize, &mut e)`"] # [doc = " returns false. This method operates in place and preserves the key"] # [doc = " associated with the retained values."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use slab::*;"] # [doc = " let mut slab = Slab::new();"] # [doc = ""] # [doc = " let k1 = slab.insert(0);"] # [doc = " let k2 = slab.insert(1);"] # [doc = " let k3 = slab.insert(2);"] # [doc = ""] # [doc = " slab.retain(|key, val| key == k1 || *val == 1);"] # [doc = ""] # [doc = " assert!(slab.contains(k1));"] # [doc = " assert!(slab.contains(k2));"] # [doc = " assert!(!slab.contains(k3));"] # [doc = ""] # [doc = " assert_eq!(2, slab.len());"] # [doc = " ```"] pub fn retain < F > (& mut self , mut f : F) where F : FnMut (usize , & mut T) -> bool , { for i in 0 .. self . entries . len () { let keep = match self . entries [i] { Entry :: Occupied (ref mut v) => f (i , v) , _ => true , } ; if ! keep { self . remove (i) ; } } } # [doc = " Return a draining iterator that removes all elements from the slab and"] # [doc = " yields the removed items."] # [doc = ""] # [doc = " Note: Elements are removed even if the iterator is only partially"] # [doc = " consumed or not consumed at all."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use slab::*;"] # [doc = " let mut slab = Slab::new();"] # [doc = ""] # [doc = " let _ = slab.insert(0);"] # [doc = " let _ = slab.insert(1);"] # [doc = " let _ = slab.insert(2);"] # [doc = ""] # [doc = " {"] # [doc = "     let mut drain = slab.drain();"] # [doc = ""] # [doc = "     assert_eq!(Some(0), drain.next());"] # [doc = "     assert_eq!(Some(1), drain.next());"] # [doc = "     assert_eq!(Some(2), drain.next());"] # [doc = "     assert_eq!(None, drain.next());"] # [doc = " }"] # [doc = ""] # [doc = " assert!(slab.is_empty());"] # [doc = " ```"] pub fn drain (& mut self) -> Drain < '_ , T > { let old_len = self . len ; self . len = 0 ; self . next = 0 ; Drain { inner : self . entries . drain (..) , len : old_len , } } }